import time


class Stopwatch:
    def __init__(self):
        self._start_time = None
        self._elapsed = 0.0
        self._laps = []
        self._running = False

    def start(self):
        if self._running:
            print("Stopwatch is already running.")
            return
        self._start_time = time.monotonic()
        self._running = True
        print("Stopwatch started.")

    def stop(self):
        if not self._running:
            print("Stopwatch is not running.")
            return
        self._elapsed += time.monotonic() - self._start_time
        self._start_time = None
        self._running = False
        print(f"Stopwatch stopped at {self._format_time(self._elapsed)}")

    def lap(self):
        if not self._running:
            print("Stopwatch is not running. Start it first.")
            return
        current = self._elapsed + (time.monotonic() - self._start_time)
        lap_number = len(self._laps) + 1
        lap_time = current - (self._laps[-1][1] if self._laps else 0.0)
        self._laps.append((lap_number, current, lap_time))
        print(f"Lap {lap_number}: {self._format_time(lap_time)} (total: {self._format_time(current)})")

    def reset(self):
        self._start_time = None
        self._elapsed = 0.0
        self._laps = []
        self._running = False
        print("Stopwatch reset.")

    def elapsed(self):
        if self._running:
            return self._elapsed + (time.monotonic() - self._start_time)
        return self._elapsed

    def display(self):
        status = "Running" if self._running else "Stopped"
        print(f"\n--- Stopwatch [{status}] ---")
        print(f"Elapsed: {self._format_time(self.elapsed())}")
        if self._laps:
            print("Laps:")
            for num, total, lap_time in self._laps:
                print(f"  Lap {num}: {self._format_time(lap_time)} (total: {self._format_time(total)})")
        print()

    @staticmethod
    def _format_time(seconds):
        mins, secs = divmod(seconds, 60)
        hours, mins = divmod(int(mins), 60)
        return f"{hours:02d}:{int(mins):02d}:{secs:06.3f}"


def main():
    sw = Stopwatch()
    commands = {
        "start": sw.start,
        "stop": sw.stop,
        "lap": sw.lap,
        "reset": sw.reset,
        "display": sw.display,
        "quit": None,
    }

    print("Stopwatch — commands: start, stop, lap, reset, display, quit")
    while True:
        try:
            cmd = input("> ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if cmd == "quit":
            break
        action = commands.get(cmd)
        if action is None:
            print(f"Unknown command. Available: {', '.join(commands)}")
        else:
            action()


if __name__ == "__main__":
    main()
